import { execSync } from "child_process";
import type { Task, OrchestratorState } from "./types.js";
import type { Logger } from "./logger.js";
import { StateStore } from "./stateStore.js";

export class IncrementalChecker {
  private repoRoot: string;
  private logDir: string;
  private logger: Logger;

  constructor(repoRoot: string, logDir: string, logger: Logger) {
    // Store params
  }

  /** Get the commit hash from the last successful run */
  getLastSuccessfulCommit(): string | null {
    // Use StateStore.findLatest(this.logDir) to load last state
    // If no state or no completedAt, return null
    // Find the base branch commit at the time of that run:
    //   The run started from a specific commit — we can use the startedAt timestamp
    //   But simpler: just return the HEAD commit hash from git log at baseBranch
    //   at the time the previous run started.
    //
    // Actually, simplest approach: store a marker file.
    // Look for .jarble-dev-last-success in logDir containing a commit hash.
    // Return that hash or null.
    try {
      const markerPath = path.join(this.logDir, '.last-success-commit');
      if (fs.existsSync(markerPath)) {
        return fs.readFileSync(markerPath, 'utf-8').trim();
      }
    } catch {}
    return null;
  }

  /** Save the current commit as the last successful run */
  saveSuccessCommit(): void {
    try {
      const hash = execSync('git rev-parse HEAD', {
        cwd: this.repoRoot, encoding: 'utf-8'
      }).trim();
      const markerPath = path.join(this.logDir, '.last-success-commit');
      fs.writeFileSync(markerPath, hash);
      this.logger.info(`Saved success commit: ${hash.slice(0, 8)}`);
    } catch (e) {
      this.logger.warn(`Failed to save success commit: ${e}`);
    }
  }

  /** Get files changed since a specific commit */
  getChangedFiles(sinceCommit: string): string[] {
    try {
      const output = execSync(`git diff --name-only ${sinceCommit}..HEAD`, {
        cwd: this.repoRoot,
        encoding: 'utf-8',
        maxBuffer: 5 * 1024 * 1024,
      });
      return output.trim().split('\n').filter(Boolean);
    } catch {
      return []; // If diff fails, assume nothing changed (safe default)
    }
  }

  /** Mark tasks as skipped if none of their touchesFiles have changed */
  markUnchangedTasks(tasks: Task[]): { skipped: string[]; running: string[] } {
    const lastCommit = this.getLastSuccessfulCommit();
    if (!lastCommit) {
      this.logger.info('No previous successful run found — running all tasks');
      return { skipped: [], running: tasks.map(t => t.name) };
    }

    const changedFiles = this.getChangedFiles(lastCommit);
    this.logger.info(`${changedFiles.length} files changed since last success (${lastCommit.slice(0, 8)})`);

    const skipped: string[] = [];
    const running: string[] = [];

    for (const task of tasks) {
      // Tasks with no touchesFiles always run (can't determine scope)
      if (task.touchesFiles.length === 0) {
        running.push(task.name);
        continue;
      }

      // Check if any of the task's files overlap with changed files
      // Use prefix matching: touchesFiles entry "jarble-api-main/src/trpc/" matches
      // changed file "jarble-api-main/src/trpc/routers/deployment.ts"
      const hasChanges = task.touchesFiles.some(tf =>
        changedFiles.some(cf =>
          cf.startsWith(tf) || tf.startsWith(cf) || cf === tf
        )
      );

      if (hasChanges) {
        running.push(task.name);
      } else {
        task.status = 'skipped';
        skipped.push(task.name);
        this.logger.info(`Skipping unchanged task: "${task.name}"`);
      }
    }

    return { skipped, running };
  }
}
```

