/** Run multiple plans sequentially (plan chaining) */
async runMultiple(plans: TaskPlan[]): Promise<OrchestratorState[]> {
  const results: OrchestratorState[] = [];
  for (const plan of plans) {
    // Reset state for each plan (keep the same runId prefix)
    this.state = {
      runId: this.state.runId + '-' + (results.length + 1),
      tasks: [],
      agents: new Map(),
      worktrees: new Map(),
      mergeResults: [],
      qualityReports: [],
      startedAt: new Date(),
    };
    this.stateStore = new StateStore(this.config.logDir, this.state.runId);

    const result = await this.run(plan);
    results.push(result);

    // Stop chaining if any plan had failures
    const failures = result.tasks.filter(t => t.status === 'failed');
    if (failures.length > 0) {
      this.logger.warn(`Plan "${plan.name}" had ${failures.length} failure(s) — stopping chain`);
      break;
    }
  }
  return results;
}
